    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Connect marker pairs that form the longest full-width/full-height axes.
    rows = [(r, [c for c, v in enumerate(grid[r]) if v == 1]) for r in range(h)]
    cols = [(c, [r for r in range(h) if grid[r][c] == 1]) for c in range(w)]
    # Lines are identified by marker pairs on opposite borders; interior aligned
    # pairs are not necessarily intended connectors.
    for r, cs in rows:
        if len(cs) >= 2 and min(cs) == 0 and max(cs) == w - 1:
            for c in range(w): out[r][c] = 1
    for c, rs in cols:
        if len(rs) >= 2 and min(rs) == 0 and max(rs) == h - 1:
            for r in range(h): out[r][c] = 1
    return out
