    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    line = set()
    # Draw straight connectors between marker pairs on each row and column.
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == 1]
        if len(cols) >= 2:
            line.update((r, c) for c in range(min(cols), max(cols) + 1))
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 1]
        if len(rows) >= 2:
            line.update((r, c) for r in range(min(rows), max(rows) + 1))
    for r, c in line:
        out[r][c] = 1
    # Recolor every 2-component touched by any connector.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
