    out = [row[:] for row in grid]
    horizontal = [r for r in range(h) if grid[r][0] == 1 and grid[r][w - 1] == 1]
    vertical = [c for c in range(w) if grid[0][c] == 1 and grid[h - 1][c] == 1]
    for r in horizontal:
        for c in range(w):
            out[r][c] = 1
    for c in vertical:
        for r in range(h):
            out[r][c] = 1
    # Vertical axes recolor a whole object only when they pass through its interior.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
