                        seen.add((yy, xx))
                        stack.append((yy, xx))
            min_c = min(x for y, x in component)
            max_c = max(x for y, x in component)
            if any(min_c < c < max_c for c in vertical):
                for y, x in component:
                    out[y][x] = 1
    return out
