    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal = [r for r in range(h) if grid[r][0] == 1 and grid[r][w-1] == 1]
    vertical = [c for c in range(w) if grid[0][c] == 1 and grid[h-1][c] == 1]
    # Draw full-length axes. They recolor background, and only object cells
    # that lie on the row/column itself (objects otherwise keep their color).
    for r in horizontal:
        for c in range(w):
            if grid[r][c] != 2: out[r][c] = 1
    for c in vertical:
        for r in range(h):
            if grid[r][c] != 2: out[r][c] = 1
    # If a rectangular block is cut through its interior, recolor it entirely.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2: continue
            left = c > 0 and grid[r][c-1] == 2
            right = c+1 < w and grid[r][c+1] == 2
            up = r > 0 and grid[r-1][c] == 2
            down = r+1 < h and grid[r+1][c] == 2
            if (c in vertical and left and right) or (r in horizontal and up and down):
                out[r][c] = 1
                # For a full rectangular object crossed internally, fill all of it.
                if c in vertical:
                    cc=c
                    while cc>0 and grid[r][cc-1]==2: cc-=1
                    c2=c
                    while c2+1<w and grid[r][c2+1]==2: c2+=1
                    for rr in range(h):
                        for xx in range(cc,c2+1):
                            if grid[rr][xx]==2: out[rr][xx]=1
                if r in horizontal:
                    rr=r
                    while rr>0 and grid[rr-1][c]==2: rr-=1
                    r2=r
                    while r2+1<h and grid[r2+1][c]==2: r2+=1
                    for yy in range(rr,r2+1):
                        for xx in range(w):
                            if grid[yy][xx]==2: out[yy][xx]=1
    return out
