    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal = [r for r in range(h) if grid[r][0] == 1 and grid[r][w-1] == 1]
    vertical = [c for c in range(w) if grid[0][c] == 1 and grid[h-1][c] == 1]
    for r in horizontal:
        for c in range(w): out[r][c] = 1
    for c in vertical:
        for r in range(h): out[r][c] = 1
    # Recolor the whole object crossed by an axis only when a solid block is
    # cut through its interior; the line itself handles partial/edge overlap.
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            minr=min(y for y,x in comp); maxr=max(y for y,x in comp)
            minc=min(x for y,x in comp); maxc=max(x for y,x in comp)
            solid=len(comp)==(maxr-minr+1)*(maxc-minc+1)
            if solid and (any(minr < rr < maxr for rr in horizontal) or any(minc < cc < maxc for cc in vertical)):
                for y,x in comp: out[y][x]=1
    return out
